fn bounded_runtime_jitter(max_inclusive: u64, salt: &str) -> u64 {
    if max_inclusive == 0 {
        return 0;
    }
    let mut hasher = Sha256::new();
    hasher.update(now_ms().to_le_bytes());
    hasher.update(salt.as_bytes());
    let digest = hasher.finalize();
    let mut bytes = [0_u8; 8];
    bytes.copy_from_slice(&digest[..8]);
    u64::from_le_bytes(bytes) % max_inclusive.saturating_add(1)
}

fn recurring_dispatch_interval_secs(paths: &AppPaths, salt: &str) -> u64 {
    let pacing = get_antibot_pacing(paths).unwrap_or(AntiBotPacingSettings {
        adaptive_protection_enabled: true,
        recurring_min_interval_secs: DEFAULT_RECURRING_MIN_INTERVAL_SECS,
        recurring_jitter_secs: DEFAULT_RECURRING_JITTER_SECS,
        enumeration_sleep_requests: DEFAULT_ENUM_SLEEP_REQUESTS,
        update_all_batch_size: DEFAULT_UPDATE_ALL_BATCH,
        recurring_download_min_sleep_secs: DEFAULT_RECURRING_DOWNLOAD_MIN_SLEEP_SECS,
        recurring_download_max_sleep_secs: DEFAULT_RECURRING_DOWNLOAD_MAX_SLEEP_SECS,
    });
    pacing
        .recurring_min_interval_secs
        .saturating_add(bounded_runtime_jitter(pacing.recurring_jitter_secs, salt))
}

fn recurring_download_sleep_secs(paths: &AppPaths, job_id: &str) -> u32 {
    let pacing = get_antibot_pacing(paths).unwrap_or(AntiBotPacingSettings {
        adaptive_protection_enabled: true,
        recurring_min_interval_secs: DEFAULT_RECURRING_MIN_INTERVAL_SECS,
        recurring_jitter_secs: DEFAULT_RECURRING_JITTER_SECS,
        enumeration_sleep_requests: DEFAULT_ENUM_SLEEP_REQUESTS,
        update_all_batch_size: DEFAULT_UPDATE_ALL_BATCH,
        recurring_download_min_sleep_secs: DEFAULT_RECURRING_DOWNLOAD_MIN_SLEEP_SECS,
        recurring_download_max_sleep_secs: DEFAULT_RECURRING_DOWNLOAD_MAX_SLEEP_SECS,
    });
    let min = pacing
        .recurring_download_min_sleep_secs
        .min(MAX_RECURRING_DOWNLOAD_SLEEP_SECS);
    let max = pacing
        .recurring_download_max_sleep_secs
        .max(min)
        .min(MAX_RECURRING_DOWNLOAD_SLEEP_SECS);
    min.saturating_add(bounded_runtime_jitter((max - min) as u64, job_id) as u32)
}

/// The safe download profile is service-based, never origin-based. A direct YouTube URL pasted
/// by the operator receives the same low-fragment, randomized-sleep behavior as a subscription
/// child; the queue track only changes scheduling priority and does not create an anti-bot hole.
fn effective_direct_download_profile(
    paths: &AppPaths,
    url: &str,
    job_id: &str,
    requested_sleep_interval: u32,
    requested_concurrent_fragments: u32,
) -> (u32, u32) {
    if is_youtube_url(url) {
        (
            requested_sleep_interval.max(recurring_download_sleep_secs(paths, job_id)),
            1,
        )
    } else {
        (requested_sleep_interval, requested_concurrent_fragments)
    }
}

/// Resolve the adaptive shared-start floor from the same canonical auth identity and saved
/// downloader baseline that the worker will use. This runs before spawning the worker so the
/// existing cross-track gate closes for the effective interval instead of allowing a burst while
/// each worker independently sleeps. Failures deliberately fall back to the saved gate interval;
/// the worker remains authoritative and will surface the underlying configuration/auth error.
#[derive(Debug, Clone)]
struct YoutubeSchedulerPolicy {
    effective: youtube_protection::DownloaderEffectivePolicy,
    next_eligible_probe_at_ms: Option<i64>,
    operation: &'static str,
    auth_fingerprint: String,
    runtime_epoch: String,
}

fn effective_youtube_scheduler_policy(
    paths: &AppPaths,
    job_id: &str,
    params_json: &str,
) -> Result<Option<YoutubeSchedulerPolicy>> {
    let params: DownloadDirectUrlParams = serde_json::from_str(params_json)?;
    let url = normalize_direct_url(&params.url)?;
    if !is_youtube_url(&url)
        || !get_antibot_pacing(paths)
            .map(|settings| settings.adaptive_protection_enabled)
            .unwrap_or(true)
    {
        return Ok(None);
    }

    let auth_cookie = resolve_youtube_auth_cookie_for_job(paths, job_id, params.auth_cookie)?;
    let browser_source = effective_youtube_browser_source(
        paths,
        auth_cookie.is_some(),
        params.use_browser_cookies,
        params.browser_cookie_source.as_deref(),
    )?;
    let auth_fingerprint = youtube_auth_material_key(
        paths,
        auth_cookie.as_deref(),
        browser_source.is_some() && auth_cookie.is_none(),
        browser_source.as_deref(),
    )?
    .unwrap_or_else(|| youtube_protection::ANONYMOUS_AUTH_FINGERPRINT.to_string());
    let runtime_epoch = youtube_protection::runtime_epoch_for_paths(paths);
    let (sleep_interval_secs, concurrent_fragments) = effective_direct_download_profile(
        paths,
        &url,
        job_id,
        params.yt_dlp_sleep_interval,
        params.yt_dlp_concurrent_fragments,
    );
    let baseline = youtube_protection::DownloaderBaselinePolicy {
        concurrent_fragments,
        sleep_interval_secs,
        sleep_requests_secs: params.yt_dlp_sleep_requests,
        update_tranche_size: 25,
        limit_rate: params.yt_dlp_limit_rate,
        throttled_rate: params.yt_dlp_throttled_rate,
    };
    let state = youtube_protection::load_policy_state(
        paths,
        youtube_protection::PROVIDER_YOUTUBE,
        youtube_protection::OPERATION_DOWNLOAD,
        &auth_fingerprint,
        &runtime_epoch,
    )?;
    let tuning = youtube_protection::get_tuning(paths)?;
    let effective =
        youtube_protection::effective_policy_with_tuning(&baseline, &state, now_ms(), &tuning);
    Ok(Some(YoutubeSchedulerPolicy {
        effective,
        next_eligible_probe_at_ms: state.next_eligible_probe_at_ms,
        operation: youtube_protection::OPERATION_DOWNLOAD,
        auth_fingerprint,
        runtime_epoch,
    }))
}

#[cfg(test)]
fn effective_youtube_start_interval_secs(
    paths: &AppPaths,
    job_id: &str,
    params_json: &str,
) -> Result<u64> {
    Ok(
        effective_youtube_scheduler_policy(paths, job_id, params_json)?
            .map(|policy| policy.effective.aggregate_start_interval_secs as u64)
            .unwrap_or(0),
    )
}

fn effective_youtube_enumeration_scheduler_policy(
    paths: &AppPaths,
    job_id: &str,
    params_json: &str,
) -> Result<Option<YoutubeSchedulerPolicy>> {
    if !get_antibot_pacing(paths)
        .map(|settings| settings.adaptive_protection_enabled)
        .unwrap_or(true)
    {
        return Ok(None);
    }
    let params: YoutubeSubscriptionRefreshV1Params = serde_json::from_str(params_json)?;
    let subscription =
        subscriptions::get_youtube_subscription_by_id(paths, &params.subscription_id)?.ok_or_else(
            || {
                EngineError::InstallFailed(format!(
                    "subscription not found: {}",
                    params.subscription_id
                ))
            },
        )?;
    let auth_cookie = resolve_youtube_auth_cookie_for_job(paths, job_id, None)?;
    let browser_source = effective_youtube_browser_source(
        paths,
        auth_cookie.is_some(),
        subscription.use_browser_cookies,
        subscription.browser_cookie_source.as_deref(),
    )?;
    let auth_fingerprint = youtube_auth_material_key(
        paths,
        auth_cookie.as_deref(),
        browser_source.is_some() && auth_cookie.is_none(),
        browser_source.as_deref(),
    )?
    .unwrap_or_else(|| youtube_protection::ANONYMOUS_AUTH_FINGERPRINT.to_string());
    let runtime_epoch = youtube_protection::runtime_epoch_for_paths(paths);
    let baseline = youtube_protection_baseline(paths)?;
    let state = youtube_protection::load_policy_state(
        paths,
        youtube_protection::PROVIDER_YOUTUBE,
        youtube_protection::OPERATION_ENUMERATION,
        &auth_fingerprint,
        &runtime_epoch,
    )?;
    let tuning = youtube_protection::get_tuning(paths)?;
    let effective =
        youtube_protection::effective_policy_with_tuning(&baseline, &state, now_ms(), &tuning);
    Ok(Some(YoutubeSchedulerPolicy {
        effective,
        next_eligible_probe_at_ms: state.next_eligible_probe_at_ms,
        operation: youtube_protection::OPERATION_ENUMERATION,
        auth_fingerprint,
        runtime_epoch,
    }))
}

fn reserve_scheduler_canary(
    paths: &AppPaths,
    job_id: &str,
    policy: Option<&YoutubeSchedulerPolicy>,
) -> Result<bool> {
    let Some(policy) = policy.filter(|policy| policy.effective.canary_only) else {
        return Ok(true);
    };
    Ok(youtube_protection::claim_cooldown_canary(
        paths,
        youtube_protection::PROVIDER_YOUTUBE,
        policy.operation,
        &policy.auth_fingerprint,
        &policy.runtime_epoch,
        job_id,
        now_ms(),
    )?
    .is_some())
}

fn claim_youtube_controlled_canary(
    paths: &AppPaths,
    job_id: &str,
    operation: &str,
    auth_fingerprint: &str,
    runtime_epoch: &str,
    effective: &youtube_protection::DownloaderEffectivePolicy,
) -> Result<()> {
    if !effective.canary_only {
        return Ok(());
    }
    if youtube_protection::claim_cooldown_canary(
        paths,
        youtube_protection::PROVIDER_YOUTUBE,
        operation,
        auth_fingerprint,
        runtime_epoch,
        job_id,
        now_ms(),
    )?
    .is_some()
    {
        Ok(())
    } else {
        Err(EngineError::InstallFailed(format!(
            "YouTube automatic protection already reserved the single controlled {} probe; no additional request was started",
            operation
        )))
    }
}

fn record_youtube_effective_command_receipt(
    paths: &AppPaths,
    job_id: &str,
    operation: &str,
    runtime_epoch: &str,
    effective: &youtube_protection::DownloaderEffectivePolicy,
) -> Result<()> {
    let details = serde_json::json!({
        "job_id": job_id,
        "operation": operation,
        "runtime_epoch": runtime_epoch,
        "mode": effective.mode.as_str(),
        "concurrent_fragments": effective.concurrent_fragments,
        "sleep_interval_secs": effective.sleep_interval_secs,
        "max_sleep_interval_secs": effective.max_sleep_interval_secs,
        "sleep_requests_secs": effective.sleep_requests_secs,
        "aggregate_start_interval_secs": effective.aggregate_start_interval_secs,
        "update_tranche_size": effective.update_tranche_size,
        "limit_rate": effective.limit_rate,
        "throttled_rate": effective.throttled_rate,
        "eligible": effective.eligible,
        "canary_only": effective.canary_only,
    });
    log_line(
        paths,
        job_id,
        "info",
        "youtube_effective_command_receipt",
        details.clone(),
    )?;
    append_engine_diagnostics_trace_row_best_effort(
        paths,
        "youtube_effective_command_receipt",
        "info",
        details,
    );
    Ok(())
}

// WP-0263: Instagram-specific (more passive) enumeration cooldown for the recurring lane.
// Read separately from the YouTube key so Meta's stricter anti-bot gets long gaps between
// profile refreshes without slowing the YouTube fleet.
pub fn instagram_recurring_min_interval_secs(paths: &AppPaths) -> u64 {
    let Ok(conn) = db::open_readonly(paths) else {
        return DEFAULT_INSTAGRAM_RECURRING_MIN_INTERVAL_SECS;
    };
    meta_u64_conn(
        &conn,
        META_KEY_INSTAGRAM_RECURRING_MIN_INTERVAL_SECS,
        DEFAULT_INSTAGRAM_RECURRING_MIN_INTERVAL_SECS,
    )
    .min(MAX_INSTAGRAM_RECURRING_MIN_INTERVAL_SECS)
}

// WP-0263: last-Instagram-enumeration-dispatch timestamp (ms). Gates how often a new Instagram
// profile enumeration is enqueued so Meta's stricter anti-bot never sees a burst — at most one
// profile refresh per `instagram_recurring_min_interval_secs`, one profile at a time.
const META_KEY_INSTAGRAM_LAST_ENUM_DISPATCH_MS: &str = "antibot_instagram_last_enum_dispatch_ms";

/// Returns true when enough time has elapsed since the last Instagram enumeration dispatch
/// (per the conservative Instagram interval) to enqueue another profile refresh. Best-effort:
/// on any DB error it returns true so pacing never becomes a hard stall.
pub fn instagram_enumeration_dispatch_allowed(paths: &AppPaths) -> bool {
    let cooldown_secs = instagram_recurring_min_interval_secs(paths);
    if cooldown_secs == 0 {
        return true;
    }
    let Ok(conn) = db::open_readonly(paths) else {
        return true;
    };
    let last_ms = meta_u64_conn(&conn, META_KEY_INSTAGRAM_LAST_ENUM_DISPATCH_MS, 0);
    if last_ms == 0 {
        return true;
    }
    let now = now_ms().max(0) as u64;
    now.saturating_sub(last_ms) >= cooldown_secs.saturating_mul(1000)
}

/// Stamp "now" as the last Instagram enumeration dispatch. Best-effort. Called after enqueuing
/// a single Instagram subscription's refresh so the next one waits the conservative interval.
pub fn record_instagram_enumeration_dispatch(paths: &AppPaths) -> Result<()> {
    let conn = db::open(paths)?;
    db::migrate(&conn)?;
    upsert_meta_conn(
        &conn,
        META_KEY_INSTAGRAM_LAST_ENUM_DISPATCH_MS,
        &(now_ms().max(0) as u64).to_string(),
    )
}

fn is_queue_paused_conn(conn: &rusqlite::Connection) -> Result<bool> {
    let value: std::result::Result<String, rusqlite::Error> = conn.query_row(
        "SELECT value FROM meta WHERE key=?1",
        [META_KEY_JOBS_QUEUE_PAUSED],
        |row| row.get(0),
    );
    match value {
        Ok(v) => {
            let v = v.trim();
            Ok(v == "1" || v.eq_ignore_ascii_case("true"))
        }
        Err(rusqlite::Error::QueryReturnedNoRows) => Ok(false),
        Err(err) => Err(EngineError::Database(err)),
    }
}

fn cleanup_output_targets_for_ui(
    targets: &[CleanupOutputDirTargetInternal],
) -> Vec<JobCleanupOutputTarget> {
    targets
        .iter()
        .map(|target| {
            let mut source_job_ids: Vec<String> = target.source_job_ids.iter().cloned().collect();
            source_job_ids.sort();
            JobCleanupOutputTarget {
                path: target.path.to_string_lossy().to_string(),
                source_job_ids,
            }
        })
        .collect()
}

fn remove_job_log_files_detailed(
    base_path: &Path,
    failures: &mut Vec<JobCleanupFailure>,
    failed_job_ids: &mut HashSet<String>,
    job_id: Option<&str>,
) -> usize {
    let mut removed = 0_usize;
    for path in std::iter::once(base_path.to_path_buf())
        .chain((1..=JOB_LOG_MAX_BACKUPS).map(|i| path_with_suffix(base_path, &format!(".{i}"))))
    {
        if !path.exists() {
            continue;
        }
        match std::fs::remove_file(&path) {
            Ok(_) => removed += 1,
            Err(err) => {
                failures.push(JobCleanupFailure {
                    scope: "job_log".to_string(),
                    path: path.to_string_lossy().to_string(),
                    message: err.to_string(),
                });
                if let Some(job_id) = job_id {
                    failed_job_ids.insert(job_id.to_string());
                }
            }
        }
    }
    removed
}

fn clear_dir_entries(dir: &Path) -> Result<usize> {
    if !dir.exists() {
        return Ok(0);
    }

    let mut removed = 0_usize;
    for entry in std::fs::read_dir(dir)? {
        let entry = match entry {
            Ok(v) => v,
            Err(_) => continue,
        };
        let path = entry.path();
        let outcome = if path.is_dir() {
            std::fs::remove_dir_all(&path)
        } else {
            std::fs::remove_file(&path)
        };
        if outcome.is_ok() {
            removed += 1;
        }
    }
    Ok(removed)
}

fn clear_dir_entries_detailed(
    dir: &Path,
    scope: &str,
    failures: &mut Vec<JobCleanupFailure>,
) -> Result<usize> {
    if !dir.exists() {
        return Ok(0);
    }

    let mut removed = 0_usize;
    for entry in std::fs::read_dir(dir)? {
        let entry = match entry {
            Ok(v) => v,
            Err(err) => {
                failures.push(JobCleanupFailure {
                    scope: scope.to_string(),
                    path: dir.to_string_lossy().to_string(),
                    message: err.to_string(),
                });
                continue;
            }
        };
        let path = entry.path();
        if remove_path_recursively(&path, scope, failures).is_ok() {
            removed += 1;
        }
    }
    Ok(removed)
}

fn remove_output_dir_targets(
    targets: &[CleanupOutputDirTargetInternal],
    scope: &str,
    failures: &mut Vec<JobCleanupFailure>,
    failed_job_ids: &mut HashSet<String>,
) -> usize {
    let mut removed = 0_usize;
    for target in targets {
        if !target.path.exists() {
            continue;
        }
        let meta = match std::fs::symlink_metadata(&target.path) {
            Ok(value) => value,
            Err(err) => {
                failures.push(JobCleanupFailure {
                    scope: scope.to_string(),
                    path: target.path.to_string_lossy().to_string(),
                    message: err.to_string(),
                });
                failed_job_ids.extend(target.source_job_ids.iter().cloned());
                continue;
            }
        };
        if !meta.is_dir() {
            failures.push(JobCleanupFailure {
                scope: scope.to_string(),
                path: target.path.to_string_lossy().to_string(),
                message: "expected an output directory but found a file".to_string(),
            });
            failed_job_ids.extend(target.source_job_ids.iter().cloned());
            continue;
        }
        if remove_path_recursively(&target.path, scope, failures).is_ok() {
            removed += 1;
        } else {
            failed_job_ids.extend(target.source_job_ids.iter().cloned());
        }
    }
    removed
}

fn remove_path_recursively(
    path: &Path,
    scope: &str,
    failures: &mut Vec<JobCleanupFailure>,
) -> std::io::Result<()> {
    let meta = match std::fs::symlink_metadata(path) {
        Ok(value) => value,
        Err(err) => {
            failures.push(JobCleanupFailure {
                scope: scope.to_string(),
                path: path.to_string_lossy().to_string(),
                message: err.to_string(),
            });
            return Err(err);
        }
    };

    let outcome = if meta.is_dir() {
        std::fs::remove_dir_all(path)
    } else {
        std::fs::remove_file(path)
    };
    if let Err(err) = outcome {
        failures.push(JobCleanupFailure {
            scope: scope.to_string(),
            path: path.to_string_lossy().to_string(),
            message: err.to_string(),
        });
        return Err(err);
    }
    Ok(())
}

fn count_job_log_files(base_path: &Path) -> usize {
    let mut count = 0_usize;
    if base_path.exists() {
        count += 1;
    }
    for i in 1..=JOB_LOG_MAX_BACKUPS {
        if path_with_suffix(base_path, &format!(".{i}")).exists() {
            count += 1;
        }
    }
    count
}

fn count_dir_entries(dir: &Path) -> Result<usize> {
    if !dir.exists() {
        return Ok(0);
    }

    let mut count = 0_usize;
    for entry in std::fs::read_dir(dir)? {
        if entry.is_ok() {
            count += 1;
        }
    }
    Ok(count)
}

fn collect_output_dir_targets(
    download_root: &Path,
    job_id: &str,
    job_type: &str,
    params_json: &str,
    out: &mut HashMap<PathBuf, CleanupOutputDirTargetInternal>,
) {
    if job_type != JobType::DownloadImageBatch.as_str() {
        return;
    }

    let Ok(params) = serde_json::from_str::<DownloadImageBatchParams>(params_json) else {
        return;
    };

    if let Some(raw_dir) = normalize_output_dir(params.output_dir) {
        let mut custom_dir = PathBuf::from(raw_dir);
        if !custom_dir.is_absolute() {
            if let Ok(cwd) = std::env::current_dir() {
                custom_dir = cwd.join(custom_dir);
            }
        }
        upsert_cleanup_output_target(out, custom_dir, CleanupOutputDirClass::External, job_id);
        return;
    }

    let subdir = params.output_subdir.trim();
    if subdir.is_empty() {
        return;
    }

    upsert_cleanup_output_target(
        out,
        download_root
            .join(DEFAULT_IMAGES_OUTPUT_SUBDIR)
            .join(subdir),
        CleanupOutputDirClass::Managed,
        job_id,
    );
    upsert_cleanup_output_target(
        out,
        download_root.join(subdir),
        CleanupOutputDirClass::Managed,
        job_id,
    );
}

fn upsert_cleanup_output_target(
    out: &mut HashMap<PathBuf, CleanupOutputDirTargetInternal>,
    path: PathBuf,
    class_name: CleanupOutputDirClass,
    job_id: &str,
) {
    use std::collections::hash_map::Entry;

    match out.entry(path.clone()) {
        Entry::Occupied(mut existing) => {
            existing.get_mut().source_job_ids.insert(job_id.to_string());
            if class_name == CleanupOutputDirClass::External {
                existing.get_mut().class_name = CleanupOutputDirClass::External;
            }
        }
        Entry::Vacant(vacant) => {
            let mut source_job_ids = HashSet::new();
            source_job_ids.insert(job_id.to_string());
            vacant.insert(CleanupOutputDirTargetInternal {
                path,
                class_name,
                source_job_ids,
            });
        }
    }
}

fn delete_terminal_jobs_by_ids(paths: &AppPaths, job_ids: &[String]) -> Result<usize> {
    if job_ids.is_empty() {
        return Ok(0);
    }

    let conn = db::open(paths)?;
    db::migrate(&conn)?;
    let tx = conn.unchecked_transaction()?;
    let mut removed = 0_usize;
    for job_id in job_ids {
        let affected = tx.execute(
            "DELETE FROM job WHERE id=?1 AND status IN (?2, ?3, ?4)",
            params![
                job_id,
                JobStatus::Succeeded.as_str(),
                JobStatus::Failed.as_str(),
                JobStatus::Canceled.as_str()
            ],
        )?;
        removed += affected;
        if affected > 0 {
            remove_job_cookie_secret(paths, job_id);
        }
    }
    tx.commit()?;
    Ok(removed)
}

fn log_line(
    paths: &AppPaths,
    job_id: &str,
    level: &str,
    event: &str,
    data: serde_json::Value,
) -> Result<()> {
    let line = serde_json::json!({
        "ts_ms": now_ms(),
        "job_id": job_id,
        "level": level,
        "event": event,
        "data": data
    })
    .to_string();

    let path = paths.job_logs_dir().join(format!("{job_id}.jsonl"));
    std::fs::create_dir_all(paths.job_logs_dir())?;
    rotate_job_log_if_needed(&path)?;
    std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)?
        .write_all(format!("{line}\n").as_bytes())?;
    Ok(())
}

fn rotate_job_log_if_needed(path: &Path) -> Result<()> {
    let len = match std::fs::metadata(path) {
        Ok(m) => m.len(),
        Err(_) => return Ok(()),
    };

    if len < JOB_LOG_ROTATE_BYTES {
        return Ok(());
    }

    rotate_file_backups(path, JOB_LOG_MAX_BACKUPS)?;
    Ok(())
}

fn rotate_file_backups(path: &Path, max_backups: usize) -> std::io::Result<()> {
    if max_backups == 0 {
        let _ = std::fs::remove_file(path);
        return Ok(());
    }

    for i in (1..=max_backups).rev() {
        let dst = path_with_suffix(path, &format!(".{i}"));
        let src = if i == 1 {
            path.to_path_buf()
        } else {
            path_with_suffix(path, &format!(".{}", i - 1))
        };

        if !src.exists() {
            continue;
        }

        if dst.exists() {
            let _ = std::fs::remove_file(&dst);
        }
        std::fs::rename(src, dst)?;
    }
    Ok(())
}

fn path_with_suffix(path: &Path, suffix: &str) -> PathBuf {
    let file_name = match path.file_name() {
        Some(n) => n.to_string_lossy().to_string(),
        None => suffix.to_string(),
    };
    path.with_file_name(format!("{file_name}{suffix}"))
}

fn prune_job_logs(paths: &AppPaths) -> Result<()> {
    let dir = paths.job_logs_dir();
    if !dir.exists() {
        return Ok(());
    }

    let now = SystemTime::now();
    let cutoff = now
        .checked_sub(Duration::from_secs(JOB_LOG_MAX_AGE_DAYS * 24 * 60 * 60))
        .unwrap_or(SystemTime::UNIX_EPOCH);

    let mut candidates: Vec<(PathBuf, SystemTime, u64)> = Vec::new();
    for entry in std::fs::read_dir(&dir)? {
        let entry = match entry {
            Ok(v) => v,
            Err(_) => continue,
        };
        let meta = match entry.metadata() {
            Ok(v) => v,
            Err(_) => continue,
        };
        if !meta.is_file() {
            continue;
        }
        let modified = meta.modified().unwrap_or(SystemTime::UNIX_EPOCH);
        let path = entry.path();
        let size = meta.len();

        if modified < cutoff {
            let _ = std::fs::remove_file(&path);
            continue;
        }

        candidates.push((path, modified, size));
    }

    candidates.sort_by_key(|(_, modified, _)| *modified);
    let mut total: u64 = candidates.iter().map(|(_, _, size)| *size).sum();
    for (path, _modified, size) in candidates {
        if total <= JOB_LOG_TOTAL_CAP_BYTES {
            break;
        }
        let _ = std::fs::remove_file(&path);
        total = total.saturating_sub(size);
    }

    Ok(())
}

fn normalize_and_expand_download_targets(
    paths: &AppPaths,
    inputs: Vec<String>,
    auth_cookie: Option<&str>,
    use_browser_cookies: bool,
    browser_cookie_source: Option<&str>,
) -> Result<Vec<DownloadTarget>> {
    let urls = normalize_direct_urls(inputs)?;
    let mut targets: Vec<DownloadTarget> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();

    // WP-0263: for Instagram profile/post expansion, resolve auth with Instagram precedence
    // (explicit cookie -> global Instagram cookie from Options). yt-dlp fallbacks still use the
    // raw `auth_cookie` argument; only the Instagram JSON-API expansion uses the global fallback.
    let instagram_auth = resolve_instagram_auth_cookie(paths, auth_cookie)?;
    let instagram_auth = instagram_auth.as_deref().or(auth_cookie);

    for url in urls {
        if is_instagram_user_profile_url(&url) {
            let remaining = MAX_DOWNLOAD_BATCH_URLS.saturating_sub(targets.len());
            if remaining == 0 {
                return Err(EngineError::InstallFailed(format!(
                    "batch limit exceeded: max {MAX_DOWNLOAD_BATCH_URLS} URLs per submission"
                )));
            }

            let expanded =
                match expand_instagram_profile_media_targets(&url, remaining + 1, instagram_auth) {
                    Ok(values) if !values.is_empty() => values,
                    Ok(_) | Err(_) => {
                        let fallback_urls = expand_yt_dlp_urls(
                            paths,
                            &url,
                            remaining + 1,
                            auth_cookie,
                            use_browser_cookies_for_url(&url, use_browser_cookies),
                            browser_cookie_source,
                        )?;
                        fallback_urls
                            .into_iter()
                            .map(|value| DownloadTarget {
                                url: value,
                                provider: DOWNLOAD_PROVIDER_YOUTUBE_YT_DLP,
                            })
                            .collect()
                    }
                };

            if expanded.is_empty() {
                return Err(EngineError::InstallFailed(format!(
                    "no downloadable entries found for {}",
                    redact_url_for_log(&url)
                )));
            }

            for candidate in expanded {
                let normalized = normalize_direct_url(&candidate.url)?;
                if !seen.insert(normalized.clone()) {
                    continue;
                }
                targets.push(DownloadTarget {
                    url: normalized,
                    provider: candidate.provider,
                });
                if targets.len() > MAX_DOWNLOAD_BATCH_URLS {
                    return Err(EngineError::InstallFailed(format!(
                        "batch limit exceeded: max {MAX_DOWNLOAD_BATCH_URLS} URLs per submission"
                    )));
                }
            }
            continue;
        }

        if is_instagram_post_like_url(&url) {
            let remaining = MAX_DOWNLOAD_BATCH_URLS.saturating_sub(targets.len());
            if remaining == 0 {
                return Err(EngineError::InstallFailed(format!(
                    "batch limit exceeded: max {MAX_DOWNLOAD_BATCH_URLS} URLs per submission"
                )));
            }

            if let Ok(expanded) = expand_instagram_post_media_targets(&url, instagram_auth) {
                if !expanded.is_empty() {
                    for candidate in expanded {
                        let normalized = normalize_direct_url(&candidate.url)?;
                        if !seen.insert(normalized.clone()) {
                            continue;
                        }
                        targets.push(DownloadTarget {
                            url: normalized,
                            provider: candidate.provider,
                        });
                        if targets.len() > MAX_DOWNLOAD_BATCH_URLS {
                            return Err(EngineError::InstallFailed(format!(
                                "batch limit exceeded: max {MAX_DOWNLOAD_BATCH_URLS} URLs per submission"
                            )));
                        }
                    }
                    continue;
                }
            }
        }

        if is_youtube_url(&url) || is_playlist_candidate_url(&url) {
            let remaining = MAX_DOWNLOAD_BATCH_URLS.saturating_sub(targets.len());
            if remaining == 0 {
                return Err(EngineError::InstallFailed(format!(
                    "batch limit exceeded: max {MAX_DOWNLOAD_BATCH_URLS} URLs per submission"
                )));
            }

            let expanded = expand_yt_dlp_urls(
                paths,
                &url,
                remaining + 1,
                auth_cookie,
                use_browser_cookies_for_url(&url, use_browser_cookies),
                browser_cookie_source,
            )?;
            if expanded.is_empty() {
                return Err(EngineError::InstallFailed(format!(
                    "no downloadable entries found for {}",
                    redact_url_for_log(&url)
                )));
            }

            for candidate in expanded {
                let normalized = normalize_direct_url(&candidate)?;
                if !seen.insert(normalized.clone()) {
                    continue;
                }
                targets.push(DownloadTarget {
                    url: normalized,
                    provider: DOWNLOAD_PROVIDER_YOUTUBE_YT_DLP,
                });
                if targets.len() > MAX_DOWNLOAD_BATCH_URLS {
                    return Err(EngineError::InstallFailed(format!(
                        "batch limit exceeded: max {MAX_DOWNLOAD_BATCH_URLS} URLs per submission"
                    )));
                }
            }
            continue;
        }

        if !seen.insert(url.clone()) {
            continue;
        }
        let instagram = is_instagram_url(&url);
        let provider = if is_likely_direct_media_url(&url) {
            DOWNLOAD_PROVIDER_DIRECT_HTTP
        } else if instagram {
            DOWNLOAD_PROVIDER_YOUTUBE_YT_DLP
        } else {
            // Most non-direct page URLs require extractor logic (embed/manifest handling).
            DOWNLOAD_PROVIDER_YOUTUBE_YT_DLP
        };
        targets.push(DownloadTarget { url, provider });
        if targets.len() > MAX_DOWNLOAD_BATCH_URLS {
            return Err(EngineError::InstallFailed(format!(
                "batch limit exceeded: max {MAX_DOWNLOAD_BATCH_URLS} URLs per submission"
            )));
        }
    }

    Ok(targets)
}

fn normalize_direct_urls(inputs: Vec<String>) -> Result<Vec<String>> {
    let mut output: Vec<String> = Vec::new();
    for input in inputs {
        for part in input.split(|ch| matches!(ch, '\n' | '\r' | '\t' | ',' | ';' | ' ')) {
            let trimmed = part.trim();
            if trimmed.is_empty() {
                continue;
            }
            let normalized = normalize_direct_url(trimmed)?;
            if !output.iter().any(|existing| existing == &normalized) {
                output.push(normalized);
            }
        }
    }
    Ok(output)
}

pub(crate) fn normalize_auth_cookie(value: Option<String>) -> Result<Option<String>> {
    let raw = value.unwrap_or_default();
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }

    if let Some(from_json) = cookie_json_to_netscape(trimmed) {
        return Ok(Some(from_json));
    }

    if let Some(from_json) = cookie_json_to_header(trimmed) {
        return Ok(Some(from_json));
    }

    if let Some(from_netscape) = normalize_netscape_cookie_text(trimmed) {
        return Ok(Some(from_netscape));
    }

    let path = Path::new(trimmed);
    if path.exists() && path.is_file() {
        let contents = std::fs::read_to_string(path)?;
        let normalized = normalize_auth_cookie(Some(contents))?;
        let normalized = normalized
            .ok_or_else(|| EngineError::InstallFailed("cookie file was empty".to_string()))?;
        return Ok(Some(normalized));
    }

    if looks_like_cookie_file_path(trimmed) {
        return Err(EngineError::InstallFailed(
            "cookie file path does not exist".to_string(),
        ));
    }

    if parse_cookie_header_pairs(trimmed).is_empty() {
        return Err(EngineError::InstallFailed(
            "session input must be a cookie header, browser-export JSON, Netscape cookie text, or an existing cookie-file path".to_string(),
        ));
    }

    Ok(Some(trimmed.to_string()))
}

pub fn normalize_youtube_auth_cookie_for_storage(value: Option<String>) -> Result<Option<String>> {
    let raw = value.unwrap_or_default();
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Ok(None);
    }

    let path = Path::new(trimmed);
    if path.exists() && path.is_file() {
        let contents = std::fs::read_to_string(path)?;
        let normalized = normalize_youtube_auth_cookie_for_storage(Some(contents))?;
        let normalized = normalized
            .ok_or_else(|| EngineError::InstallFailed("cookie file was empty".to_string()))?;
        return Ok(Some(normalized));
    }
    if looks_like_cookie_file_path(trimmed) {
        return Err(EngineError::InstallFailed(
            "cookie file path does not exist".to_string(),
        ));
    }

    if let Some(records) = cookie_records_from_structured_input(trimmed) {
        let filtered = filter_youtube_cookie_records(records);
        if filtered.is_empty() {
            return Err(EngineError::InstallFailed(
                "cookie export did not contain non-expired youtube.com cookies. Export a YouTube-only cookies.txt/JSON from a logged-in youtube.com browser session.".to_string(),
            ));
        }
        return Ok(format_netscape_cookie_records(&filtered));
    }

    let pairs = parse_cookie_header_pairs(trimmed);
    if pairs.is_empty() {
        return Err(EngineError::InstallFailed(
            "session input must be a cookie header, browser-export JSON, Netscape cookie text, or an existing cookie-file path".to_string(),
        ));
    }
    Ok(Some(cookie_pairs_to_netscape_text_for_url(
        "https://www.youtube.com/robots.txt",
        &pairs,
    )?))
}

/// Auth command errors are operator-visible and copied into capability receipts. Remove local
/// credential-file locators while retaining the surrounding failure reason. This is deliberately
/// narrower than diagnostics redaction: auth targets remain visible, credential filesystem paths
/// do not.
pub fn redact_auth_credential_locators(message: &str) -> String {
    static QUOTED_WINDOWS_PATH: OnceLock<Regex> = OnceLock::new();
    static BARE_WINDOWS_PATH: OnceLock<Regex> = OnceLock::new();
    static QUOTED_PRIVATE_UNIX_PATH: OnceLock<Regex> = OnceLock::new();
    static BARE_PRIVATE_UNIX_PATH: OnceLock<Regex> = OnceLock::new();

    let quoted_windows = QUOTED_WINDOWS_PATH.get_or_init(|| {
        Regex::new(r#"(?i)(?:\"(?:[a-z]:\\|\\\\)[^\"]+\"|'(?:[a-z]:\\|\\\\)[^']+')"#)
            .expect("quoted auth path regex")
    });
    let bare_windows = BARE_WINDOWS_PATH.get_or_init(|| {
        Regex::new(r#"(?i)(?:[a-z]:\\|\\\\)[^\s\"'<>]+"#).expect("bare auth path regex")
    });
    let quoted_unix = QUOTED_PRIVATE_UNIX_PATH.get_or_init(|| {
        Regex::new(r#"(?:\"/(?:Users|home|tmp|var|private|run)/[^\"]+\"|'/(?:Users|home|tmp|var|private|run)/[^']+')"#)
            .expect("quoted private auth path regex")
    });
    let bare_unix = BARE_PRIVATE_UNIX_PATH.get_or_init(|| {
        Regex::new(r#"/(?:Users|home|tmp|var|private|run)/[^\s\"'<>]+"#)
            .expect("bare private auth path regex")
    });

    let redacted = quoted_windows.replace_all(message, "<credential_locator_redacted>");
    let redacted = bare_windows.replace_all(&redacted, "<credential_locator_redacted>");
    let redacted = quoted_unix.replace_all(&redacted, "<credential_locator_redacted>");
    bare_unix
        .replace_all(&redacted, "<credential_locator_redacted>")
        .to_string()
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NetscapeCookieRecord {
    domain: String,
    include_subdomains: bool,
    path: String,
    secure: bool,
    expires: i64,
    name: String,
    value: String,
    http_only: bool,
}

fn normalize_cookie_name(value: &str) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty()
        || trimmed.contains(' ')
        || trimmed.contains('\t')
        || trimmed.contains('\r')
        || trimmed.contains('\n')
        || trimmed.contains(';')
        || trimmed.contains('=')
    {
        return None;
    }
    Some(trimmed.to_string())
}

fn normalize_cookie_value(value: &str) -> Option<String> {
    if value.contains('\t') || value.contains('\r') || value.contains('\n') {
        return None;
    }
    Some(value.trim().to_string())
}

fn normalize_cookie_domain(value: &str) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty()
        || trimmed.contains('\t')
        || trimmed.contains('\r')
        || trimmed.contains('\n')
        || trimmed.contains(' ')
    {
        return None;
    }
    Some(trimmed.to_ascii_lowercase())
}

fn normalize_cookie_path_value(value: Option<&str>) -> String {
    let trimmed = value.unwrap_or("/").trim();
    if trimmed.is_empty() {
        "/".to_string()
    } else {
        trimmed.to_string()
    }
}

fn cookie_json_expiration(value: Option<&serde_json::Value>, session: bool) -> i64 {
    if session {
        return 0;
    }
    value
        .and_then(|raw| {
            raw.as_i64()
                .or_else(|| raw.as_u64().and_then(|v| i64::try_from(v).ok()))
                .or_else(|| raw.as_f64().map(|v| v.floor() as i64))
        })
        .unwrap_or(2_147_483_647)
        .max(0)
}

fn cookie_json_record_from_object(
    map: &serde_json::Map<String, serde_json::Value>,
) -> Option<NetscapeCookieRecord> {
    let name = normalize_cookie_name(map.get("name")?.as_str()?)?;
    let value = normalize_cookie_value(map.get("value")?.as_str()?)?;
    let mut domain = normalize_cookie_domain(map.get("domain")?.as_str()?)?;
    let host_only = map
        .get("hostOnly")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    if host_only {
        domain = domain.trim_start_matches('.').to_string();
    } else if !domain.starts_with('.') {
        domain = format!(".{domain}");
    }
    let path = normalize_cookie_path_value(map.get("path").and_then(serde_json::Value::as_str));
    let secure = map
        .get("secure")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let session = map
        .get("session")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let http_only = map
        .get("httpOnly")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let expires = cookie_json_expiration(map.get("expirationDate"), session);
    Some(NetscapeCookieRecord {
        domain,
        include_subdomains: !host_only,
        path,
        secure,
        expires,
        name,
        value,
        http_only,
    })
}

fn format_netscape_cookie_records(records: &[NetscapeCookieRecord]) -> Option<String> {
    if records.is_empty() {
        return None;
    }

    let mut dedup_seen: HashSet<String> = HashSet::new();
    let mut dedup_records: Vec<NetscapeCookieRecord> = Vec::new();
    for record in records.iter().rev() {
        let key = format!("{}\t{}\t{}", record.domain, record.path, record.name);
        if dedup_seen.insert(key) {
            dedup_records.push(record.clone());
        }
    }
    dedup_records.reverse();

    let mut contents = String::from("# Netscape HTTP Cookie File\n");
    for record in dedup_records {
        let line_domain = if record.http_only {
            format!("#HttpOnly_{}", record.domain)
        } else {
            record.domain.clone()
        };
        contents.push_str(&format!(
            "{line_domain}\t{}\t{}\t{}\t{}\t{}\t{}\n",
            if record.include_subdomains {
                "TRUE"
            } else {
                "FALSE"
            },
            record.path,
            if record.secure { "TRUE" } else { "FALSE" },
            record.expires.max(0),
            record.name,
            record.value
        ));
    }
    Some(contents)
}

fn cookie_records_from_structured_input(raw: &str) -> Option<Vec<NetscapeCookieRecord>> {
    if let Ok(value) = serde_json::from_str::<serde_json::Value>(raw) {
        let mut records = Vec::new();
        collect_cookie_json_records(&value, &mut records);
        return Some(records);
    }
    let records = netscape_cookie_text_to_records(raw);
    if records.is_empty() {
        None
    } else {
        Some(records)
    }
}

fn collect_cookie_json_records(value: &serde_json::Value, records: &mut Vec<NetscapeCookieRecord>) {
    match value {
        serde_json::Value::Array(values) => {
            for item in values {
                collect_cookie_json_records(item, records);
            }
        }
        serde_json::Value::Object(map) => {
            if let Some(record) = cookie_json_record_from_object(map) {
                records.push(record);
                return;
            }
            if let Some(cookies) = map.get("cookies") {
                collect_cookie_json_records(cookies, records);
                return;
            }
            for nested in map.values() {
                if matches!(
                    nested,
                    serde_json::Value::Array(_) | serde_json::Value::Object(_)
                ) {
                    collect_cookie_json_records(nested, records);
                }
            }
        }
        _ => {}
    }
}

fn is_youtube_cookie_domain(domain: &str) -> bool {
    let normalized = domain
        .trim()
        .trim_start_matches("#HttpOnly_")
        .trim_start_matches('.')
        .to_ascii_lowercase();
    normalized == "youtube.com"
        || normalized.ends_with(".youtube.com")
        || normalized == "youtu.be"
        || normalized.ends_with(".youtu.be")
}

fn filter_youtube_cookie_records(records: Vec<NetscapeCookieRecord>) -> Vec<NetscapeCookieRecord> {
    let now_secs = (now_ms() / 1000).max(0);
    records
        .into_iter()
        .filter(|record| is_youtube_cookie_domain(&record.domain))
        .filter(|record| record.expires == 0 || record.expires >= now_secs)
        .collect()
}

fn netscape_cookie_text_to_records(raw_text: &str) -> Vec<NetscapeCookieRecord> {
    let mut records: Vec<NetscapeCookieRecord> = Vec::new();
    for line in raw_text.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let (http_only, payload) = if let Some(rest) = trimmed.strip_prefix("#HttpOnly_") {
            (true, rest)
        } else if trimmed.starts_with('#') {
            continue;
        } else {
            (false, trimmed)
        };
        let parts: Vec<&str> = payload.split('\t').collect();
        if parts.len() < 7 {
            continue;
        }
        let Some(domain) = normalize_cookie_domain(parts[0]) else {
            continue;
        };
        let Some(name) = normalize_cookie_name(parts[5]) else {
            continue;
        };
        let Some(value) = normalize_cookie_value(parts[6]) else {
            continue;
        };
        let include_subdomains = parts[1].trim().eq_ignore_ascii_case("true");
        let path = normalize_cookie_path_value(Some(parts[2]));
        let secure = parts[3].trim().eq_ignore_ascii_case("true");
        let expires = parts[4].trim().parse::<i64>().unwrap_or(0).max(0);
        records.push(NetscapeCookieRecord {
            domain,
            include_subdomains,
            path,
            secure,
            expires,
            name,
            value,
            http_only,
        });
    }
    records
}

fn normalize_netscape_cookie_text(raw_text: &str) -> Option<String> {
    let records = netscape_cookie_text_to_records(raw_text);
    format_netscape_cookie_records(&records)
}

fn looks_like_cookie_file_path(value: &str) -> bool {
    if value.contains('\n') || value.contains('\r') {
        return false;
    }

    let bytes = value.as_bytes();
    if value.starts_with("\\\\") || value.starts_with('/') {
        return true;
    }
    if bytes.len() >= 3
        && bytes[1] == b':'
        && bytes[0].is_ascii_alphabetic()
        && (bytes[2] == b'\\' || bytes[2] == b'/')
    {
        return true;
    }

    let lower = value.to_ascii_lowercase();
    [".json", ".txt", ".js", ".cookie", ".cookies"]
        .iter()
        .any(|suffix| lower.ends_with(suffix))
}

fn cookie_pairs_to_header(pairs: &[(String, String)]) -> Option<String> {
    if pairs.is_empty() {
        return None;
    }
    Some(
        pairs
            .iter()
            .map(|(name, value)| format!("{name}={value}"))
            .collect::<Vec<_>>()
            .join("; "),
    )
}

fn netscape_cookie_text_to_header(raw_text: &str) -> Option<String> {
    let pairs: Vec<(String, String)> = netscape_cookie_text_to_records(raw_text)
        .into_iter()
        .map(|record| (record.name, record.value))
        .collect();
    cookie_pairs_to_header(&pairs)
}

fn normalize_output_subdir(value: Option<String>) -> Option<String> {
    let raw = value.unwrap_or_default();
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return None;
    }
    let safe = sanitize_filename_component(trimmed);
    if safe.is_empty() {
        None
    } else {
        Some(safe)
    }
}

fn normalize_output_dir(value: Option<String>) -> Option<String> {
    let raw = value.unwrap_or_default();
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed.to_string())
    }
}

fn parse_cookie_header_pairs(cookie_header: &str) -> Vec<(String, String)> {
    let mut pairs: Vec<(String, String)> = Vec::new();
    for part in cookie_header.split(';') {
        let trimmed = part.trim();
        if trimmed.is_empty() {
            continue;
        }
        let Some((name, value)) = trimmed.split_once('=') else {
            continue;
        };
        let name = name.trim();
        if name.is_empty() || name.contains(' ') || name.contains('\t') {
            continue;
        }
        pairs.push((name.to_string(), value.trim().to_string()));
    }
    pairs
}

fn cookie_file_domain_for_url(url: &str) -> Result<String> {
    let parsed = Url::parse(url).map_err(|_| {
        EngineError::InstallFailed(format!(
            "invalid URL for cookies: {}",
            redact_url_for_log(url)
        ))
    })?;
    let host = parsed
        .host_str()
        .ok_or_else(|| EngineError::InstallFailed("cookie URL missing host".to_string()))?
        .to_ascii_lowercase();
    if host == "youtube.com" || host.ends_with(".youtube.com") || host == "youtu.be" {
        Ok(".youtube.com".to_string())
    } else if host.ends_with("instagram.com") {
        Ok(".instagram.com".to_string())
    } else {
        Ok(host)
    }
}

fn cookie_pairs_to_netscape_text_for_url(url: &str, pairs: &[(String, String)]) -> Result<String> {
    let domain = cookie_file_domain_for_url(url)?;
    let include_subdomains = domain.starts_with('.');
    let secure = url.to_ascii_lowercase().starts_with("https://");
    let records = pairs
        .iter()
        .map(|(name, value)| NetscapeCookieRecord {
            domain: domain.clone(),
            include_subdomains,
            path: "/".to_string(),
            secure,
            expires: 2_147_483_647,
            name: name.clone(),
            value: value.clone(),
            http_only: false,
        })
        .collect::<Vec<_>>();
    format_netscape_cookie_records(&records).ok_or_else(|| {
        EngineError::InstallFailed("cookie value did not contain valid key=value pairs".to_string())
    })
}

fn auth_cookie_to_netscape_text(url: &str, auth_cookie: &str) -> Result<String> {
    if let Some(netscape) = normalize_netscape_cookie_text(auth_cookie) {
        return Ok(netscape);
    }
    let pairs = parse_cookie_header_pairs(auth_cookie);
    if pairs.is_empty() {
        return Err(EngineError::InstallFailed(
            "cookie value did not contain valid key=value pairs".to_string(),
        ));
    }
    cookie_pairs_to_netscape_text_for_url(url, &pairs)
}

fn write_auth_cookie_as_netscape_file(
    paths: &AppPaths,
    job_id: &str,
    url: &str,
    auth_cookie: &str,
) -> Result<PathBuf> {
    let artifacts_dir = paths.job_artifacts_dir(job_id);
    std::fs::create_dir_all(&artifacts_dir)?;
    let cookie_path = artifacts_dir.join("yt_dlp_cookies.txt");
    let contents = auth_cookie_to_netscape_text(url, auth_cookie)?;
    persistence::atomic_write_text(&cookie_path, &contents)?;
    Ok(cookie_path)
}

fn write_auth_cookie_as_netscape_temp_file(
    paths: &AppPaths,
    url: &str,
    auth_cookie: &str,
) -> Result<PathBuf> {
    let dir = paths.cache_dir().join("yt_dlp_cookie_files");
    std::fs::create_dir_all(&dir)?;
    let cookie_path = dir.join(format!("cookie_{}.txt", Uuid::new_v4()));
    let contents = auth_cookie_to_netscape_text(url, auth_cookie)?;
    persistence::atomic_write_text(&cookie_path, &contents)?;
    Ok(cookie_path)
}

fn strip_browser_cookie_args(args: &mut Vec<String>) -> bool {
    let mut i = 0_usize;
    while i < args.len() {
        if args[i] == "--cookies-from-browser" {
            args.remove(i);
            if i < args.len() {
                args.remove(i);
            }
            return true;
        }
        i += 1;
    }
    false
}

fn strip_yt_dlp_option_with_value(args: &mut Vec<String>, option: &str) -> bool {
    let mut i = 0_usize;
    while i < args.len() {
        if args[i] == option {
            args.remove(i);
            if i < args.len() {
                args.remove(i);
            }
            return true;
        }
        i += 1;
    }
    false
}

fn strip_all_yt_dlp_options_with_value(args: &mut Vec<String>, option: &str) -> usize {
    let mut removed = 0_usize;
    while strip_yt_dlp_option_with_value(args, option) {
        removed += 1;
    }
    removed
}

/// The final managed-video container is an engine policy, not a saved-preset choice. Remove
/// any stale/conflicting finalizer before appending the canonical options last, so old queued
/// jobs and custom presets cannot create a new MP4 artifact.
fn enforce_managed_video_yt_dlp_options(args: &mut Vec<String>) {
    strip_all_yt_dlp_options_with_value(args, "--merge-output-format");
    strip_all_yt_dlp_options_with_value(args, "--remux-video");
    args.retain(|arg| arg != "--keep-video" && arg != "--no-keep-video");
    args.push("--merge-output-format".to_string());
    args.push(MANAGED_VIDEO_CONTAINER.to_string());
    args.push("--remux-video".to_string());
    args.push(MANAGED_VIDEO_CONTAINER.to_string());
    // Successful post-processing must not leave the original MP4/WebM as a second deliverable.
    args.push("--no-keep-video".to_string());
}

/// Saved presets choose source quality, never the final managed container. Historical and
/// custom selectors commonly pin `bv` to MP4 and `ba` to M4A; remove only those container
/// constraints while preserving the selector's ordering, fallbacks, codec and quality terms.
fn neutralize_managed_video_format_selector(selector: &str) -> String {
    fn contains_bare_format_id(selector: &str) -> bool {
        let chars = selector.chars().collect::<Vec<_>>();
        let mut bracket_depth = 0_u32;
        let mut index = 0_usize;
        while index < chars.len() {
            match chars[index] {
                '[' => {
                    bracket_depth += 1;
                    index += 1;
                }
                ']' => {
                    bracket_depth = bracket_depth.saturating_sub(1);
                    index += 1;
                }
                character if bracket_depth == 0 && character.is_ascii_digit() => {
                    let start = index;
                    while index < chars.len() && chars[index].is_ascii_digit() {
                        index += 1;
                    }
                    let before = start
                        .checked_sub(1)
                        .and_then(|value| chars.get(value))
                        .copied();
                    let after = chars.get(index).copied();
                    let boundary_before = before.is_none_or(|value| {
                        value.is_whitespace() || matches!(value, '+' | '/' | ',' | '(')
                    });
                    let boundary_after = after.is_none_or(|value| {
                        value.is_whitespace() || matches!(value, '+' | '/' | ',' | ')' | '[')
                    });
                    if boundary_before && boundary_after {
                        return true;
                    }
                }
                _ => index += 1,
            }
        }
        false
    }

    // Numeric yt-dlp format IDs encode a provider-specific container/codec choice (for example
    // YouTube 137+140 pins MP4 video plus M4A audio). Their meaning is not stable enough to
    // rewrite component-by-component, so map the whole saved selector back to neutral source
    // intent. Final resolution still honors the separate quality preference through `-S`.
    if contains_bare_format_id(selector) {
        return "bv*+ba/b".to_string();
    }

    fn pins_forbidden_container(expression: &str) -> bool {
        let lower = expression.to_ascii_lowercase();
        for field in ["ext", "container", "vcodec", "acodec", "codec", "format"] {
            let mut remainder = lower.as_str();
            while let Some(index) = remainder.find(field) {
                let after = remainder[index + field.len()..].trim_start();
                if after.starts_with("!=") || after.starts_with("!~") {
                    remainder = &after[2..];
                    continue;
                }
                let value = ["~=", "^=", "$=", "*=", "="]
                    .iter()
                    .find_map(|operator| after.strip_prefix(operator))
                    .map(|value| {
                        value
                            .split(['|', '&', ',', '/'])
                            .next()
                            .unwrap_or(value)
                            .trim()
                            .trim_matches(['\'', '"'])
                    });
                if value.is_some_and(|value| value.contains("mp4") || value.contains("m4a")) {
                    return true;
                }
                remainder = &after[1.min(after.len())..];
            }
        }
        false
    }

    let mut output = String::with_capacity(selector.len());
    let mut cursor = 0;
    while let Some(open_rel) = selector[cursor..].find('[') {
        let open = cursor + open_rel;
        output.push_str(&selector[cursor..open]);
        let Some(close_rel) = selector[open + 1..].find(']') else {
            output.push_str(&selector[open..]);
            return output;
        };
        let close = open + 1 + close_rel;
        let expression = &selector[open + 1..close];
        if !pins_forbidden_container(expression) {
            output.push_str(&selector[open..=close]);
        }
        cursor = close + 1;
    }
    output.push_str(&selector[cursor..]);
    output
}

fn yt_dlp_should_retry_without_format(url: &str, err: &EngineError) -> bool {
    let lower = err.to_string().to_ascii_lowercase();
    lower.contains("requested format is not available")
        || lower.contains("yt-dlp downloaded an empty file")
        || (is_youtube_url(url)
            && (lower.contains("http error 403") || lower.contains("fragment 1 not found")))
}

fn yt_dlp_is_rate_limit_error(message: &str) -> bool {
    youtube_protection::classify_youtube_outcome(Some(message))
        == youtube_protection::DownloaderOutcomeClass::RateLimited
}

fn yt_dlp_rate_limit_retry_delay_secs(attempt: u32) -> u64 {
    let delay = YT_DLP_RATE_LIMIT_MIN_DELAY_SECS << attempt;
    delay.min(YT_DLP_RATE_LIMIT_MAX_DELAY_SECS)
}

fn run_yt_dlp_with_rate_limit_retry(
    paths: &AppPaths,
    args: &[String],
    job_id: Option<&str>,
    timeout_secs: u64,
    using_browser_cookies: bool,
    expected_path_root: Option<&Path>,
    url: &str,
    output_res: Result<std::process::Output>,
) -> Result<std::process::Output> {
    let mut output_res = output_res;
    let mut retries = 0u32;
    loop {
        match output_res {
            Ok(output) => return Ok(output),
            Err(err) => {
                if retries >= YT_DLP_RATE_LIMIT_RETRIES
                    || !is_youtube_url(url)
                    || !yt_dlp_is_rate_limit_error(&err.to_string())
                {
                    return Err(err);
                }
            }
        };

        retries += 1;
        let delay = yt_dlp_rate_limit_retry_delay_secs(retries - 1);
        std::thread::sleep(Duration::from_secs(delay));
        output_res = run_yt_dlp_with_browser_cookie_retry(
            paths,
            args,
            job_id,
            timeout_secs,
            using_browser_cookies,
            expected_path_root,
        );
    }
}

fn yt_dlp_is_http_403_error(message: &str) -> bool {
    message.to_ascii_lowercase().contains("http error 403")
}

fn run_yt_dlp_with_dependency_refresh_retry(
    _paths: &AppPaths,
    _args: &[String],
    _job_id: Option<&str>,
    _timeout_secs: u64,
    url: &str,
    output_res: Result<std::process::Output>,
) -> Result<std::process::Output> {
    let first_err = match output_res {
        Ok(output) => return Ok(output),
        Err(err) => err,
    };

    let _was_youtube_403 = is_youtube_url(url) && yt_dlp_is_http_403_error(&first_err.to_string());
    // A healthy, hash-verified pinned runtime is never mutated in response to remote HTTP
    // evidence. The 403 must reach the adaptive classifier unchanged; readiness repair occurs
    // before launch when the bundled runtime is actually absent or invalid.
    Err(first_err)
}

fn run_yt_dlp_with_browser_cookie_retry(
    paths: &AppPaths,
    args: &[String],
    job_id: Option<&str>,
    timeout_secs: u64,
    using_browser_cookies: bool,
    expected_path_root: Option<&Path>,
) -> Result<std::process::Output> {
    match run_yt_dlp(paths, args, job_id, timeout_secs, expected_path_root) {
        Ok(output) => Ok(output),
        Err(first_err) => {
            if !using_browser_cookies {
                return Err(first_err);
            }

            let mut retry_args = args.to_vec();
            if !strip_browser_cookie_args(&mut retry_args) {
                return Err(first_err);
            }

            match run_yt_dlp(paths, &retry_args, job_id, timeout_secs, expected_path_root) {
                Ok(output) => Ok(output),
                Err(second_err) => Err(EngineError::InstallFailed(format!(
                    "{first_err}; retry without browser cookies failed: {second_err}"
                ))),
            }
        }
    }
}

fn cookie_json_to_netscape(raw_json: &str) -> Option<String> {
    let value: serde_json::Value = serde_json::from_str(raw_json).ok()?;
    let mut records: Vec<NetscapeCookieRecord> = Vec::new();

    fn collect(value: &serde_json::Value, records: &mut Vec<NetscapeCookieRecord>) {
        match value {
            serde_json::Value::Array(values) => {
                for item in values {
                    collect(item, records);
                }
            }
            serde_json::Value::Object(map) => {
                if let Some(record) = cookie_json_record_from_object(map) {
                    records.push(record);
                    return;
                }
                if let Some(cookies) = map.get("cookies") {
                    collect(cookies, records);
                    return;
                }
                for nested in map.values() {
                    if matches!(
                        nested,
                        serde_json::Value::Array(_) | serde_json::Value::Object(_)
                    ) {
                        collect(nested, records);
                    }
                }
            }
            _ => {}
        }
    }

    collect(&value, &mut records);
    format_netscape_cookie_records(&records)
}

fn cookie_json_to_header(raw_json: &str) -> Option<String> {
    let value: serde_json::Value = serde_json::from_str(raw_json).ok()?;
    let mut pairs: Vec<(String, String)> = Vec::new();

    fn push_pair(pairs: &mut Vec<(String, String)>, name: &str, value: &str) {
        let name = name.trim();
        if name.is_empty() || name.contains(';') || name.contains('=') {
            return;
        }
        pairs.push((name.to_string(), value.trim().to_string()));
    }

    fn collect(value: &serde_json::Value, pairs: &mut Vec<(String, String)>) {
        match value {
            serde_json::Value::Array(values) => {
                for item in values {
                    collect(item, pairs);
                }
            }
            serde_json::Value::Object(map) => {
                if let (Some(name), Some(value)) = (map.get("name"), map.get("value")) {
                    if let (Some(name), Some(value)) = (name.as_str(), value.as_str()) {
                        push_pair(pairs, name, value);
                    }
                    return;
                }
                if let Some(cookies) = map.get("cookies") {
                    collect(cookies, pairs);
                    return;
                }
                for (key, value) in map {
                    if let Some(value) = value.as_str() {
                        push_pair(pairs, key, value);
                    }
                }
            }
            serde_json::Value::String(value) => {
                if let Some((name, v)) = value.trim().split_once('=') {
                    push_pair(pairs, name, v);
                }
            }
            _ => {}
        }
    }

    collect(&value, &mut pairs);
    if pairs.is_empty() {
        return None;
    }

    let mut dedup_seen: HashSet<String> = HashSet::new();
    let mut dedup_pairs: Vec<(String, String)> = Vec::new();
    for (name, value) in pairs.into_iter().rev() {
        if dedup_seen.insert(name.clone()) {
            dedup_pairs.push((name, value));
        }
    }
    dedup_pairs.reverse();

    cookie_pairs_to_header(&dedup_pairs)
}

fn strip_range_query_params(raw_url: &str) -> String {
    let mut parsed = match Url::parse(raw_url) {
        Ok(v) => v,
        Err(_) => return raw_url.to_string(),
    };
    let pairs: Vec<(String, String)> = parsed.query_pairs().into_owned().collect();
    if pairs.is_empty() {
        return raw_url.to_string();
    }

    let mut kept: Vec<(String, String)> = Vec::new();
    for (k, v) in pairs {
        let key = k.to_ascii_lowercase();
        if key == "range"
            || key == "bytestart"
            || key == "byteend"
            || key == "start"
            || key == "end"
        {
            continue;
        }
        kept.push((k, v));
    }
    if kept.is_empty() {
        parsed.set_query(None);
        return parsed.to_string();
    }

    parsed.set_query(None);
    let mut serializer = url::form_urlencoded::Serializer::new(String::new());
    for (k, v) in kept {
        serializer.append_pair(&k, &v);
    }
    let query = serializer.finish();
    parsed.set_query(Some(&query));
    parsed.to_string()
}

fn normalize_direct_url(value: &str) -> Result<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Err(EngineError::InstallFailed("empty URL provided".to_string()));
    }
    let redacted = redact_url_for_log(trimmed);

    let uri: ureq::http::Uri = trimmed
        .parse()
        .map_err(|_| EngineError::InstallFailed("invalid URL format".to_string()))?;

    let scheme = uri.scheme_str().unwrap_or_default();
    if scheme != "http" && scheme != "https" {
        return Err(EngineError::InstallFailed(format!(
            "unsupported URL scheme for {redacted}; only http/https are allowed"
        )));
    }
    if uri.authority().is_none() {
        return Err(EngineError::InstallFailed(format!(
            "URL is missing host: {redacted}"
        )));
    }

    Ok(trimmed.to_string())
}

fn redact_url_for_log(value: &str) -> String {
    match value.parse::<ureq::http::Uri>() {
        Ok(uri) => {
            let scheme = uri.scheme_str().unwrap_or("http");
            let authority = uri
                .authority()
                .map(|a| a.as_str().to_string())
                .unwrap_or_else(|| "unknown-host".to_string());
            format!("{scheme}://{authority}/...")
        }
        Err(_) => "[invalid-url]".to_string(),
    }
}

// Engine diagnostics have one producer/consumer boundary: the desktop-installed
// bounded sink. The desktop is the sole writer for trace rotation, capture state,
// incident traces and manifests.
fn append_engine_diagnostics_trace_row_best_effort(
    paths: &AppPaths,
    event: &str,
    level: &str,
    details: serde_json::Value,
) {
    crate::diagnostics::emit_trace_event(paths, event, level, details);
}

pub(crate) fn append_youtube_archive_on_success(
    paths: &AppPaths,
    subscription_id: &str,
    url: &str,
) -> Result<()> {
    let Some(video_id) = subscriptions::youtube_video_id_from_url(url) else {
        return Ok(());
    };

    let Some(_sub) = subscriptions::get_youtube_subscription_by_id(paths, subscription_id)? else {
        return Ok(());
    };
    subscriptions::merge_youtube_archive_member(paths, subscription_id, &video_id)?;
    Ok(())
}

fn host_from_url(url: &str) -> Option<String> {
    url.parse::<ureq::http::Uri>()
        .ok()?
        .authority()
        .map(|a| a.as_str().to_ascii_lowercase())
}

fn is_youtube_url(url: &str) -> bool {
    let host = match host_from_url(url) {
        Some(v) => v,
        None => return false,
    };

    host == "youtube.com"
        || host == "www.youtube.com"
        || host == "m.youtube.com"
        || host == "music.youtube.com"
        || host == "youtu.be"
        || host.ends_with(".youtube.com")
}

fn is_instagram_url(url: &str) -> bool {
    let host = match host_from_url(url) {
        Some(v) => v,
        None => return false,
    };
    host == "instagram.com" || host == "www.instagram.com" || host.ends_with(".instagram.com")
}

fn is_instagram_media_asset_url(url: &str) -> bool {
    let parsed = match url.parse::<ureq::http::Uri>() {
        Ok(value) => value,
        Err(_) => return false,
    };
    let host = parsed
        .authority()
        .map(|authority| authority.host().to_ascii_lowercase())
        .unwrap_or_default();
    if host.contains("instagram") {
        return true;
    }
    if !host.ends_with("fbcdn.net") {
        return false;
    }
    parsed.path().to_ascii_lowercase().contains("instagram")
}

fn instagram_username_from_url(url: &str) -> Option<String> {
    if !is_instagram_url(url) {
        return None;
    }
    let parsed = url.parse::<ureq::http::Uri>().ok()?;
    let segments: Vec<&str> = parsed
        .path()
        .split('/')
        .filter(|part| !part.trim().is_empty())
        .collect();
    if segments.is_empty() {
        return None;
    }

    let first = segments[0].to_ascii_lowercase();
    let reserved = [
        "p", "reel", "reels", "tv", "stories", "explore", "accounts", "direct", "api", "graphql",
        "about",
    ];
    if reserved.iter().any(|value| *value == first) {
        return None;
    }
    if !first
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || ch == '.' || ch == '_')
    {
        return None;
    }
    Some(first)
}

fn is_instagram_user_profile_url(url: &str) -> bool {
    instagram_username_from_url(url).is_some()
}

fn is_instagram_post_like_url(url: &str) -> bool {
    if !is_instagram_url(url) {
        return false;
    }
    let parsed = match url.parse::<ureq::http::Uri>() {
        Ok(v) => v,
        Err(_) => return false,
    };
    let path = parsed.path().to_ascii_lowercase();
    path.starts_with("/p/")
        || path.starts_with("/reel/")
        || path.starts_with("/reels/")
        || path.starts_with("/tv/")
}

fn instagram_shortcode_from_url(url: &str) -> Option<String> {
    if !is_instagram_post_like_url(url) {
        return None;
    }
    let parsed = url.parse::<ureq::http::Uri>().ok()?;
    let segments: Vec<&str> = parsed
        .path()
        .split('/')
        .filter(|part| !part.trim().is_empty())
        .collect();
    if segments.len() < 2 {
        return None;
    }
    let shortcode = segments[1].trim();
    if shortcode.is_empty() {
        None
    } else {
        Some(shortcode.to_string())
    }
}

fn instagram_shortcode_to_media_id(shortcode: &str) -> Option<String> {
    if shortcode.trim().is_empty() {
        return None;
    }
    const ALPHABET: &str = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let mut value: u128 = 0;
    for ch in shortcode.chars() {
        let index = ALPHABET.find(ch)? as u128;
        value = value.checked_mul(64)?;
        value = value.checked_add(index)?;
    }
    Some(value.to_string())
}

fn is_likely_youtube_video_url(url: &str) -> bool {
    let uri = match url.parse::<ureq::http::Uri>() {
        Ok(v) => v,
        Err(_) => return false,
    };

    let host = uri
        .authority()
        .map(|a| a.as_str().to_ascii_lowercase())
        .unwrap_or_default();
    let path = uri.path();
    if host == "youtu.be" {
        return true;
    }
    if path.starts_with("/shorts/") || path.starts_with("/live/") {
        return true;
    }
    path.starts_with("/watch")
}

fn effective_download_provider(provider: &str, url: &str) -> &'static str {
    let normalized = provider.trim();
    if is_instagram_url(url) && is_likely_direct_media_url(url) {
        return DOWNLOAD_PROVIDER_DIRECT_HTTP;
    }
    if normalized == DOWNLOAD_PROVIDER_YOUTUBE_YT_DLP
        || is_youtube_url(url)
        || is_instagram_url(url)
    {
        DOWNLOAD_PROVIDER_YOUTUBE_YT_DLP
    } else {
        DOWNLOAD_PROVIDER_DIRECT_HTTP
    }
}

fn is_playlist_candidate_url(url: &str) -> bool {
    if is_youtube_url(url) {
        let path = url
            .parse::<ureq::http::Uri>()
            .ok()
            .map(|u| u.path().to_string())
            .unwrap_or_default();
        // Single youtube videos are expanded earlier and should stay single-file at download step.
        return !(path.starts_with("/watch")
            || path.starts_with("/shorts/")
            || path.starts_with("/live/")
            || url.contains("youtu.be/"));
    }
    if is_instagram_url(url) {
        let path = url
            .parse::<ureq::http::Uri>()
            .ok()
            .map(|u| u.path().to_ascii_lowercase())
            .unwrap_or_default();
        // /p/, /reel/, /tv/ are usually single posts; profiles should expand.
        return !(path.starts_with("/p/")
            || path.starts_with("/reel/")
            || path.starts_with("/tv/")
            || path.starts_with("/stories/"));
    }
    false
}

fn use_browser_cookies_for_url(url: &str, requested: bool) -> bool {
    let _ = url;
    requested
}

pub fn normalize_browser_cookie_source(value: Option<&str>) -> Result<Option<String>> {
    let Some(raw) = value.map(str::trim).filter(|v| !v.is_empty()) else {
        return Ok(None);
    };
    let normalized = raw.to_ascii_lowercase();
    if SUPPORTED_BROWSER_COOKIE_SOURCES.contains(&normalized.as_str()) {
        Ok(Some(normalized))
    } else {
        Err(EngineError::InstallFailed(format!(
            "unsupported browser cookie source: {raw}. Choose firefox, chrome, edge, or opera."
        )))
    }
}

fn browser_cookie_source_for_request(
    use_browser_cookies: bool,
    source: Option<&str>,
) -> Result<Option<String>> {
    if !use_browser_cookies {
        return Ok(None);
    }
    Ok(Some(
        normalize_browser_cookie_source(source)?
            .unwrap_or_else(|| DEFAULT_BROWSER_COOKIE_SOURCE.to_string()),
    ))
}

fn yt_dlp_youtube_player_clients(
    auth_cookie_present: bool,
    js_runtime_available: bool,
) -> Option<&'static str> {
    if js_runtime_available {
        // When a JavaScript runtime is available, let yt-dlp use its documented defaults.
        return None;
    }
    if auth_cookie_present {
        Some("tv_downgraded,web_safari,web")
    } else {
        Some("android_sdkless,web_safari,web")
    }
}

fn append_yt_dlp_runtime_args(
    paths: &AppPaths,
    args: &mut Vec<String>,
    url: &str,
    auth_cookie_present: bool,
) -> Result<bool> {
    if !is_youtube_url(url) {
        return Ok(false);
    }
    let provider = tools::ensure_youtube_po_provider(paths)?;
    let provider_port = provider.port.ok_or_else(|| {
        EngineError::InstallFailed(
            "localhost PO provider did not report its bound port".to_string(),
        )
    })?;
    args.push("--plugin-dirs".to_string());
    args.push(
        paths
            .youtube_po_provider_plugin_dir()
            .to_string_lossy()
            .to_string(),
    );
    let js_runtime = tools::preferred_ytdlp_js_runtime_arg(paths);
    if let Some(spec) = js_runtime.as_ref() {
        args.push("--js-runtimes".to_string());
        args.push(spec.clone());
    }
    let mut extractor_args = vec![format!(
        "youtubepot-bgutilhttp:base_url=http://127.0.0.1:{provider_port}"
    )];
    if let Some(clients) = yt_dlp_youtube_player_clients(auth_cookie_present, js_runtime.is_some())
    {
        extractor_args.push(format!("youtube:player_client={clients}"));
    }
    args.push("--extractor-args".to_string());
    args.push(extractor_args.join(";"));
    Ok(js_runtime.is_some())
}

fn yt_dlp_failure_hint(
    url: &str,
    error_text: &str,
    using_browser_cookies: bool,
    auth_cookie_present: bool,
    js_runtime_available: bool,
) -> Option<String> {
    let lower = error_text.to_ascii_lowercase();
    if lower.contains("could not copy chrome cookie database") {
        return Some(
            "Browser-cookie access failed because Chrome's cookie database was locked. Turn off browser cookies for this run or close Chrome and retry.".to_string(),
        );
    }
    if lower.contains("failed to decrypt with dpapi") {
        return Some(
            "Browser-cookie access failed because Windows would not let yt-dlp decrypt the Chromium cookie store. Use a fresh exported YouTube cookies.txt/Netscape cookie file, or use a browser/profile that yt-dlp can read.".to_string(),
        );
    }
    if is_youtube_url(url) && lower.contains("sign in to confirm") {
        if auth_cookie_present {
            return Some(
                "VoxVulgi saved YouTube cookies were supplied, but YouTube rejected them. Re-export a fresh YouTube-only Netscape cookies.txt from the logged-in browser session and run the auth preflight before queueing another subscription batch.".to_string(),
            );
        }
        if using_browser_cookies {
            return Some(
                "VoxVulgi asked yt-dlp to read browser cookies, but YouTube still rejected the request. Export a fresh YouTube-only Netscape cookies.txt instead of relying on live browser cookie access.".to_string(),
            );
        }
        return Some(
            "YouTube requested sign-in and this run did not have usable cookies. Add a fresh YouTube cookie export or enable a working browser-cookie source before retrying.".to_string(),
        );
    }
    if is_youtube_url(url) && lower.contains("the page needs to be reloaded") {
        let runtime_hint = if js_runtime_available {
            " VoxVulgi already supplied a JavaScript runtime for this run, so retrying after a bundled yt-dlp refresh is the next safe step."
        } else {
            " Install the bundled Deno JavaScript runtime in Diagnostics and retry so yt-dlp can evaluate YouTube's current extraction scripts."
        };
        return Some(format!(
            "YouTube's extractor asked for a page reload instead of returning playable media.{runtime_hint}"
        ));
    }
    if is_youtube_url(url) && yt_dlp_is_rate_limit_error(&lower) {
        return Some(
            "YouTube is rate-limiting this session (HTTP 429 / too many requests). Wait before retrying, then run with slower pacing (increase sleep interval/request settings) so requests are spaced out."
                .to_string(),
        );
    }
    if is_youtube_url(url) && lower.contains("http error 403") {
        let auth_hint = if auth_cookie_present {
            " VoxVulgi already preferred auth-safe YouTube clients for this run."
        } else {
            " VoxVulgi already preferred conservative public YouTube clients for this run."
        };
        let runtime_hint = if js_runtime_available {
            " VoxVulgi also supplied a JavaScript runtime."
        } else {
            " If this is a public video, install the bundled Deno JavaScript runtime and retry before adding session material."
        };
        return Some(format!(
            "YouTube rejected the selected client/format with HTTP 403.{auth_hint}{runtime_hint} If this persists for the same URL, refresh the bundled yt-dlp runtime. Only add an explicit session if the video truly requires sign-in."
        ));
    }
    if is_instagram_url(url) && lower.contains("unable to extract data") {
        let auth_note = if auth_cookie_present || using_browser_cookies {
            " Explicit session input is still the preferred path for profile/post expansion."
        } else {
            " Many Instagram profile/post URLs require an explicit exported session."
        };
        return Some(format!(
            "Instagram's extractor returned no usable media data for this URL.{auth_note}"
        ));
    }
    None
}

fn append_yt_dlp_archive_download_options(
    args: &mut Vec<String>,
    subtitle_mode: Option<&str>,
    concurrent_fragments: u32,
    throttled_rate: &str,
    file_access_retries: u32,
    sleep_interval: u32,
    max_sleep_interval: u32,
    sleep_requests: u32,
) {
    let concurrent_fragments = normalize_positive_u32(
        concurrent_fragments,
        YT_DLP_ARCHIVE_CONCURRENT_FRAGMENTS_U32,
    )
    .to_string();
    let file_access_retries =
        normalize_positive_u32(file_access_retries, YT_DLP_ARCHIVE_FILE_ACCESS_RETRIES_U32)
            .to_string();

    args.push("-N".to_string());
    args.push(concurrent_fragments);
    args.push("--throttled-rate".to_string());
    args.push(
        normalize_non_empty(Some(throttled_rate))
            .unwrap_or_else(|| YT_DLP_ARCHIVE_THROTTLED_RATE.to_string()),
    );
    args.push("--file-access-retries".to_string());
    args.push(file_access_retries);

    if sleep_interval > 0 {
        args.push("--sleep-interval".to_string());
        args.push(sleep_interval.to_string());
        if max_sleep_interval >= sleep_interval {
            args.push("--max-sleep-interval".to_string());
            args.push(max_sleep_interval.to_string());
        }
    }
    if sleep_requests > 0 {
        args.push("--sleep-requests".to_string());
        args.push(sleep_requests.to_string());
    }

    match normalize_non_empty(subtitle_mode)
        .as_deref()
        .map(str::to_ascii_lowercase)
        .as_deref()
    {
        Some("auto") | Some("embed") | Some("auto_srt") | Some("auto-srt") => {
            // Auto means every selected subtitle source: prefer authored subtitles and also
            // allow automatic captions. --embed-subs removes yt-dlp's temporary subtitle file
            // after the postprocessor succeeds; the later exact-content check is the final
            // guard before any surviving sidecar is removed.
            args.push("--embed-subs".to_string());
            args.push("--write-subs".to_string());
            args.push("--write-auto-subs".to_string());
            args.push("--sub-langs".to_string());
            args.push(YT_DLP_ARCHIVE_SUB_LANGS.to_string());
            args.push("--convert-subs".to_string());
            args.push("srt".to_string());
        }
        Some("manual") | Some("subs") | Some("srt") | Some("sidecar") => {
            args.push("--embed-subs".to_string());
            args.push("--write-subs".to_string());
            args.push("--sub-langs".to_string());
            args.push(YT_DLP_ARCHIVE_SUB_LANGS.to_string());
            args.push("--convert-subs".to_string());
            args.push("srt".to_string());
        }
        _ => {}
    }
}

fn append_yt_dlp_limit_rate_option(args: &mut Vec<String>, limit_rate: Option<&str>) {
    if let Some(limit_rate) = normalize_non_empty(limit_rate) {
        args.push("--limit-rate".to_string());
        args.push(limit_rate);
    }
}

